{
  "path": [
    {
      "step": 1,
      "course_id": "COU1568",
      "rationale": "Begin with a foundational course on databases, covering the basics of database concepts, including relational design, indexing, and query tuning."
    },
    {
      "step": 2,
      "course_id": "COU38",
      "rationale": "Following the foundational course, introduce the Structured Query Language (SQL) to provide learners with a deeper understanding of database querying and manipulation."
    },
    {
      "step": 3,
      "course_id": "COU450",
      "rationale": "With a solid understanding of SQL, learners can now move on to an intermediate-level course on database management essentials, covering topics such as database design, entity-relationship modeling, and database administration."
    },
    {
      "step": 4,
      "course_id": "COU6388",
      "rationale": "Building on the intermediate-level course, learners can now explore advanced topics in relational database administration, including database security, database servers, and database administration."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX541",
      "rationale": "This foundational calculus course covers the basics of algebra, geometry, and calculus, providing a solid foundation for further learning."
    },
    {
      "step": 2,
      "course_id": "EDX1192",
      "rationale": "Building on the foundational concepts from EDX541, this course covers limits, continuity, and differentiation in engineering calculus, as well as applications of derivatives."
    },
    {
      "step": 3,
      "course_id": "EDX2110",
      "rationale": "This course focuses on differential calculus, covering how derivatives relate to the slope of a function, differentiation rules, and the concept of the second derivative."
    },
    {
      "step": 4,
      "course_id": "EDX1297",
      "rationale": "This course covers calculus I, including differentiation techniques, integration techniques, and solving ordinary differential equations."
    },
    {
      "step": 5,
      "course_id": "EDX591",
      "rationale": "This course covers multivariable functions, including visualization, partial derivatives, directional derivatives, and critical points."
    },
    {
      "step": 6,
      "course_id": "EDX365",
      "rationale": "This course focuses on derivatives, including limits, derivatives, and applications of derivatives, preparing the learner for the AP Calculus AB exam."
    },
    {
      "step": 7,
      "course_id": "EDX2011",
      "rationale": "This course covers integrals, including applications of integrals, differential equations, and slope fields, preparing the learner for the AP Calculus AB exam."
    },
    {
      "step": 8,
      "course_id": "EDX1163",
      "rationale": "This course covers the basics of kinematics, work and energy, momentum and collisions, and conservation laws, providing a solid foundation for further learning in mechanics."
    },
    {
      "step": 9,
      "course_id": "EDX1775",
      "rationale": "This course covers the basics of differential equations, including kinematics, work and energy, momentum and collisions, and conservation laws, providing a solid foundation for further learning in mechanics."
    },
    {
      "step": 10,
      "course_id": "EDX2477",
      "rationale": "This course covers the application of calculus to real-world problems, including data modeling, derivatives, and mathematical modeling."
    }
  ]
}

