learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "EDX3229",
      "rationale": "This foundational course covers the basics of project management, including project scope, risk, time, and costs. It provides a solid understanding of project management principles, which will be built upon in later courses."
    },
    {
      "step": 2,
      "course_id": "EDX3248",
      "rationale": "This course builds on the foundational knowledge of project management by introducing Agile Project Management. It covers the differences between Agile and traditional approaches, and provides skills to engage in adaptive planning, facilitate continuous improvement, assess project quality, and mitigate risks."
    },
    {
      "step": 3,
      "course_id": "EDX2132",
      "rationale": "This course focuses on storytelling and its application in project management. It helps learners create a vision and status stories for their projects, and utilize stories to manage risks and negotiate with stakeholders."
    },
    {
      "step": 4,
      "course_id": "EDX1325",
      "rationale": "This course covers Agile Process, Project, and Program Controls, which is a natural progression from Agile Project Management. It provides essential methods for managing people, process, and product on empowered teams, and how to always be closing (ABC) with every project increment using a definition of done."
    },
    {
      "step": 5,
      "course_id": "EDX3342",
      "rationale": "This course introduces Strategic Project Management, which is a natural progression from Agile Process, Project, and Program Controls. It provides the ability to move beyond basic project management by applying strategic principles to effectively and successfully lead projects."
    },
    {
      "step": 6,
      "course_id": "EDX3346",
      "rationale": "This course covers Change Management for Digital Transformation, which is a natural progression from Strategic Project Management. It provides contemporary techniques for effectively managing change in digital projects and digital transformation efforts."
    }
  ]
}

