learning_path:
{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1337",
      "rationale": "Foundational course covering the essential functions and services of public health in both the domestic United States and international settings."
    },
    {
      "step": 2,
      "course_id": "EDX1896",
      "rationale": "Builds on the foundational knowledge of public health by introducing the role of John Snow in creating modern epidemiology and the importance of effective communication about epidemics."
    },
    {
      "step": 3,
      "course_id": "EDX1084",
      "rationale": "Introduces basic inferential statistics and how to create and interpret graphical summaries of data, which is essential for understanding and analyzing public health data."
    },
    {
      "step": 4,
      "course_id": "EDX3062",
      "rationale": "Fosters a conceptual framework for understanding the relationship between quality and population health, and how to assess and improve healthcare quality."
    },
    {
      "step": 5,
      "course_id": "EDX1221",
      "rationale": "Applies the knowledge of public health and epidemiology to understand the biology of the malaria parasite, the mosquito vector, and the human host, and how to inform local and national malaria policymaking."
    },
    {
      "step": 6,
      "course_id": "EDX1424",
      "rationale": "Employs the knowledge of public health and epidemiology to develop strategies for injury prevention in children and teens, including advocacy, health inequities, and transportation safety."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "COU1306",
      "rationale": "This course provides a foundational understanding of mental health and its importance in humanitarian settings, which is essential for a support worker."
    },
    {
      "step": 2,
      "course_id": "EDX1845",
      "rationale": "This course builds on the previous one by providing a deeper understanding of mental health, including how to recognize and respond to mental health concerns."
    },
    {
      "step": 3,
      "course_id": "EDX2097",
      "rationale": "This course introduces the learner to mental health theory and practice, including the application of theories and perspectives to real-world scenarios."
    },
    {
      "step": 4,
      "course_id": "EDX1728",
      "rationale": "This course develops the learner's skills in health coaching, which is essential for a support worker to effectively motivate and coach their patients."
    },
    {
      "step": 5,
      "course_id": "EDX1841",
      "rationale": "This course provides a comprehensive understanding of mental health, including strategies to increase mental fitness and recognize risk factors for mental health crisis and suicidality."
    },
    {
      "step": 6,
      "course_id": "EDX105",
      "rationale": "This course builds on the previous one by providing a deeper understanding of mental health history and treatment, including the impact of stigma surrounding mental health disorders and care."
    },
    {
      "step": 7,
      "course_id": "EDX2818",
      "rationale": "This course introduces the learner to clinical psychology, including common psychological disorders and treatments, which is essential for a support worker to understand the complexities of mental health."
    },
    {
      "step": 8,
      "course_id": "EDX2943",
      "rationale": "This course develops the learner's skills in spiritual competency training in mental health, which is essential for a support worker to effectively integrate spirituality and religion into clinical practice."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX2198",
      "rationale": "This course provides foundational knowledge in human anatomy and physiology, covering the cellular and molecular levels, and the organization of the human body. It lays the groundwork for further study in anatomy and physiology."
    },
    {
      "step": 2,
      "course_id": "EDX2844",
      "rationale": "Building on the foundational knowledge from EDX2198, this course delves deeper into the human body systems, focusing on seven of the 11 body systems, including the endocrine, circulatory, immune, respiratory, digestive, excretory, and reproductive systems."
    },
    {
      "step": 3,
      "course_id": "EDX2437",
      "rationale": "This course provides advanced knowledge in mechanical ventilation, which is a critical aspect of nursing care, especially in critical care settings. It builds on the anatomy and physiology knowledge from EDX2198 and EDX2844."
    },
    {
      "step": 4,
      "course_id": "EDX2201",
      "rationale": "As a nursing student, it's essential to understand the role of preceptors in nursing education. This course provides knowledge on preceptor roles and responsibilities, which is crucial for effective clinical teaching and learning experiences."
    },
    {
      "step": 5,
      "course_id": "EDX3353",
      "rationale": "To prepare for a nursing program, it's essential to develop leadership competencies. This course provides strategies to enhance management and leadership competencies, making better leadership decisions, and driving healthcare innovation."
    }
  ]
}

{
  "path": [
    {
      "step": 1,
      "course_id": "EDX1844",
      "rationale": "Foundational knowledge of global health systems and healthcare policy requires an understanding of the basics of programming and data analysis."
    },
    {
      "step": 2,
      "course_id": "EDX2416",
      "rationale": "Introduction to SQL provides a solid foundation for data analysis and manipulation, which is essential for understanding global health systems and healthcare policy."
    },
    {
      "step": 3,
      "course_id": "EDX2149",
      "rationale": "Excel for Everyone: Core Foundations provides hands-on experience with data analysis and visualization, which is crucial for understanding and working with global health data."
    },
    {
      "step": 4,
      "course_id": "EDX873",
      "rationale": "Analyzing Data with Python provides practical experience with data analysis and machine learning, which is essential for understanding and working with complex global health data."
    },
    {
      "step": 5,
      "course_id": "EDX3352",
      "rationale": "Machine Learning: Practical Applications provides a comprehensive understanding of machine learning concepts and techniques, which is crucial for working with large and complex global health data sets."
    },
    {
      "step": 6,
      "course_id": "EDX3300",
      "rationale": "Artificial Intelligence in Health Care provides an in-depth understanding of AI and ML fundamentals, specifically through the lens of its applicability in health care, which is essential for working with global health data."
    }
  ]
}

